"""Route, API key and quota policy models with validation and mtime hot reload."""

from __future__ import annotations

import hashlib
import json
import os
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional

ALGORITHMS = ("token-bucket", "leaky-bucket", "sliding-window")
ANY_TENANT = "*"
ANY_SCOPE = "*"
EMPTY_CONFIG: Dict[str, Any] = {"routes": [], "keys": [], "quota_policies": []}


class GatewayError(Exception):
    """A rejected configuration or request; ``status`` is the HTTP status to use."""

    def __init__(self, message: str, status: int = 400) -> None:
        super().__init__(message)
        self.message = str(message)
        self.status = int(status)


def sha256_hex(text: str) -> str:
    return hashlib.sha256((text or "").encode("utf-8")).hexdigest()


def _get(data: Dict[str, Any], key: str, kind: type, where: str,
         default: Any = None, required: bool = False) -> Any:
    if key not in data or data[key] is None:
        if required:
            raise GatewayError("%s: missing field %r" % (where, key))
        return default
    value = data[key]
    bad = (kind is int and isinstance(value, bool)) or not isinstance(value, kind)
    if bad:
        raise GatewayError("%s: field %r must be %s" % (where, key, kind.__name__))
    return value


def _str_map(data: Dict[str, Any], key: str, where: str) -> Dict[str, str]:
    raw = _get(data, key, dict, where, default={})
    if any(not isinstance(k, str) or not isinstance(v, (str, int, float)) for k, v in raw.items()):
        raise GatewayError("%s: %r entries must map string to scalar" % (where, key))
    return {str(k): str(v) for k, v in raw.items()}


def _str_list(data: Dict[str, Any], key: str, where: str) -> List[str]:
    raw = _get(data, key, list, where, default=[])
    if any(not isinstance(item, str) for item in raw):
        raise GatewayError("%s: %r entries must be strings" % (where, key))
    return list(raw)


def _unique(items: List[Any], pick: Callable[[Any], str], label: str) -> None:
    seen = set()
    for item in items:
        if pick(item) in seen:
            raise GatewayError("duplicate %s id: %s" % (label, pick(item)))
        seen.add(pick(item))


@dataclass
class Route:
    """One routing rule: match a method plus path prefix onto an upstream."""

    id: str
    tenant: str
    method: str
    path_prefix: str
    upstream: str
    auth_required: bool = True
    weight: int = 1
    request_headers: Dict[str, str] = field(default_factory=dict)
    response_headers: Dict[str, str] = field(default_factory=dict)
    quota_policy: Optional[str] = None
    timeout_ms: int = 5000
    scopes: List[str] = field(default_factory=list)

    @classmethod
    def from_dict(cls, data: Any, where: str = "route") -> "Route":
        if not isinstance(data, dict):
            raise GatewayError("%s: must be a JSON object" % where)
        route_id = _get(data, "id", str, where, required=True)
        where = "route %s" % route_id
        match = _get(data, "match", dict, where, required=True)
        method = _get(match, "method", str, "%s match" % where, default="*").upper()
        prefix = _get(match, "path_prefix", str, "%s match" % where, required=True)
        if not prefix.startswith("/"):
            raise GatewayError("%s: path_prefix must start with '/'" % where)
        weight = _get(data, "weight", int, where, default=1)
        timeout_ms = _get(data, "timeout_ms", int, where, default=5000)
        if weight < 1 or timeout_ms < 1:
            raise GatewayError("%s: weight and timeout_ms must be >= 1" % where)
        transform = _get(data, "transform", dict, where, default={})
        return cls(id=route_id, tenant=_get(data, "tenant", str, where, default=ANY_TENANT),
                   method=method, path_prefix=prefix,
                   upstream=_get(data, "upstream", str, where, required=True),
                   auth_required=_get(data, "auth_required", bool, where, default=True),
                   weight=weight,
                   request_headers=_str_map(transform, "request_headers", "%s transform" % where),
                   response_headers=_str_map(transform, "response_headers", "%s transform" % where),
                   quota_policy=_get(data, "quota_policy", str, where),
                   timeout_ms=timeout_ms, scopes=_str_list(data, "scopes", where))

    def to_dict(self) -> Dict[str, Any]:
        return {"id": self.id, "tenant": self.tenant,
                "match": {"method": self.method, "path_prefix": self.path_prefix},
                "upstream": self.upstream, "auth_required": self.auth_required,
                "weight": self.weight, "quota_policy": self.quota_policy,
                "timeout_ms": self.timeout_ms, "scopes": list(self.scopes),
                "transform": {"request_headers": dict(self.request_headers),
                              "response_headers": dict(self.response_headers)}}

    def matches(self, method: str, path: str, tenant: Optional[str]) -> bool:
        """``tenant`` of None matches any tenant, so a request can reach the auth step."""
        if self.method not in ("*", method.upper()):
            return False
        if tenant is not None and self.tenant not in (ANY_TENANT, tenant):
            return False
        return path.startswith(self.path_prefix)


@dataclass
class ApiKey:
    """An API key; only the sha256 of the secret is ever stored."""

    key_id: str
    tenant: str
    secret_sha256: str
    scopes: List[str] = field(default_factory=list)

    @classmethod
    def from_dict(cls, data: Any, where: str = "key") -> "ApiKey":
        if not isinstance(data, dict):
            raise GatewayError("%s: must be a JSON object" % where)
        key_id = _get(data, "key_id", str, where, required=True)
        where = "key %s" % key_id
        digest = _get(data, "secret_sha256", str, where, required=True)
        if len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
            raise GatewayError("%s: secret_sha256 must be 64 lowercase hex characters" % where)
        return cls(key_id, _get(data, "tenant", str, where, default=ANY_TENANT), digest,
                   _str_list(data, "scopes", where))

    def allows(self, required: List[str]) -> bool:
        return not required or ANY_SCOPE in self.scopes or set(required).issubset(set(self.scopes))

    def to_dict(self) -> Dict[str, Any]:
        return {"key_id": self.key_id, "tenant": self.tenant, "scopes": list(self.scopes),
                "secret_sha256": self.secret_sha256}

    def public(self) -> Dict[str, Any]:
        return {"key_id": self.key_id, "tenant": self.tenant, "scopes": list(self.scopes)}


@dataclass
class QuotaPolicy:
    """A named rate limit policy; one bucket instance is kept per policy id."""

    id: str
    tenant: str
    algorithm: str
    limit: int
    window_ms: int
    burst: Optional[int] = None

    @classmethod
    def from_dict(cls, data: Any, where: str = "quota policy") -> "QuotaPolicy":
        if not isinstance(data, dict):
            raise GatewayError("%s: must be a JSON object" % where)
        policy_id = _get(data, "id", str, where, required=True)
        where = "quota policy %s" % policy_id
        algorithm = _get(data, "algorithm", str, where, required=True)
        if algorithm not in ALGORITHMS:
            raise GatewayError("%s: algorithm must be one of %s" % (where, ", ".join(ALGORITHMS)))
        limit = _get(data, "limit", int, where, required=True)
        window_ms = _get(data, "window_ms", int, where, required=True)
        burst = _get(data, "burst", int, where)
        if limit < 1 or window_ms < 1 or (burst is not None and burst < 1):
            raise GatewayError("%s: limit, window_ms and burst must be >= 1" % where)
        return cls(policy_id, _get(data, "tenant", str, where, default=ANY_TENANT),
                   algorithm, limit, window_ms, burst)

    def capacity(self) -> int:
        return self.burst or self.limit

    def rate_per_ms(self) -> float:
        return self.limit / float(self.window_ms)

    def signature(self) -> tuple:
        return (self.algorithm, self.limit, self.window_ms, self.burst)

    def to_dict(self) -> Dict[str, Any]:
        out = {"id": self.id, "tenant": self.tenant, "algorithm": self.algorithm,
               "limit": self.limit, "window_ms": self.window_ms}
        if self.burst is not None:
            out["burst"] = self.burst
        return out


@dataclass
class GatewayConfig:
    routes: List[Route] = field(default_factory=list)
    keys: List[ApiKey] = field(default_factory=list)
    policies: List[QuotaPolicy] = field(default_factory=list)
    revision: int = 0

    def matching_routes(self, method: str, path: str, tenant: Optional[str]) -> List[Route]:
        return [r for r in self.routes if r.matches(method, path, tenant)]

    def key(self, key_id: str) -> Optional[ApiKey]:
        return next((k for k in self.keys if k.key_id == key_id), None)

    def sanitized(self) -> Dict[str, Any]:
        return {"revision": self.revision, "routes": [r.to_dict() for r in self.routes],
                "keys": [k.public() for k in self.keys],
                "quota_policies": [p.to_dict() for p in self.policies]}


def _list(raw: Dict[str, Any], key: str) -> List[Any]:
    value = raw.get(key, [])
    if value is None:
        return []
    if not isinstance(value, list):
        raise GatewayError("config: %r must be a JSON array" % key)
    return value


def parse(raw: Any) -> GatewayConfig:
    """Validate a decoded config document and build a :class:`GatewayConfig`."""
    if not isinstance(raw, dict):
        raise GatewayError("config root must be a JSON object")
    routes = [Route.from_dict(item, "route[%d]" % i) for i, item in enumerate(_list(raw, "routes"))]
    keys = [ApiKey.from_dict(item, "key[%d]" % i) for i, item in enumerate(_list(raw, "keys"))]
    policies = [QuotaPolicy.from_dict(item, "quota_policy[%d]" % i)
                for i, item in enumerate(_list(raw, "quota_policies"))]
    _unique(routes, lambda r: r.id, "route")
    _unique(keys, lambda k: k.key_id, "api key")
    _unique(policies, lambda p: p.id, "quota policy")
    known = {p.id for p in policies}
    for route in routes:
        if route.quota_policy and route.quota_policy not in known:
            raise GatewayError("route %s: unknown quota_policy %r" % (route.id, route.quota_policy))
    return GatewayConfig(routes, keys, policies)


def load(path: str, revision: int = 0) -> GatewayConfig:
    """Read and validate ``path``; raise :class:`GatewayError` when malformed."""
    try:
        with open(path, "r", encoding="utf-8") as handle:
            raw = json.load(handle)
    except FileNotFoundError:
        raise GatewayError("config file not found: %s" % path)
    except OSError as exc:
        raise GatewayError("config file unreadable: %s: %s" % (path, exc))
    except ValueError as exc:
        raise GatewayError("config file is not valid JSON: %s: %s" % (path, exc))
    config = parse(raw)
    config.revision = revision
    return config


def read_raw(path: str) -> Dict[str, Any]:
    """Return the editable document at ``path`` (an empty template when absent)."""
    if not os.path.exists(path):
        return json.loads(json.dumps(EMPTY_CONFIG))
    try:
        with open(path, "r", encoding="utf-8") as handle:
            raw = json.load(handle)
    except ValueError as exc:
        raise GatewayError("config file is not valid JSON: %s: %s" % (path, exc))
    if not isinstance(raw, dict):
        raise GatewayError("config root must be a JSON object")
    for key in EMPTY_CONFIG:
        raw.setdefault(key, [])
    return raw


def save_config(path: str, raw: Dict[str, Any]) -> None:
    """Atomically replace ``path`` with ``raw``."""
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as handle:
        json.dump(raw, handle, indent=2, sort_keys=True)
        handle.write("\n")
    os.replace(tmp, path)


class ConfigStore:
    """Holds the live config and reloads it when the file mtime changes."""

    def __init__(self, path: Optional[str] = None) -> None:
        self.path = path
        self.ready = True
        self.last_error: Optional[str] = None
        self._config = GatewayConfig()
        self._revision = 0
        self._mtime_ns: Optional[int] = None
        if path:
            self.load()

    @property
    def config(self) -> GatewayConfig:
        return self._config

    @property
    def revision(self) -> int:
        return self._revision

    def adopt(self, config: GatewayConfig, mtime_ns: Optional[int] = None) -> GatewayConfig:
        self._revision += 1
        config.revision = self._revision
        self._config = config
        self._mtime_ns = self._mtime() if mtime_ns is None else mtime_ns
        self.ready = True
        self.last_error = None
        return config

    def load(self) -> GatewayConfig:
        if not self.path:
            raise GatewayError("no config path configured")
        return self.adopt(load(self.path))

    def _mtime(self) -> Optional[int]:
        if not self.path:
            return None
        try:
            return os.stat(self.path).st_mtime_ns
        except OSError:
            return None

    def reload_if_changed(self) -> bool:
        """Reload only when the mtime moved; keep the last good config on error."""
        if not self.path:
            return False
        mtime = self._mtime()
        if mtime is None:
            self.ready, self.last_error = False, "config file not found: %s" % self.path
            return False
        if self._mtime_ns is not None and mtime == self._mtime_ns:
            return False
        try:
            config = load(self.path)
        except GatewayError as exc:
            self._mtime_ns, self.ready, self.last_error = mtime, False, exc.message
            return False
        self.adopt(config, mtime_ns=mtime)
        return True


_STORES: Dict[str, ConfigStore] = {}


def reload_if_changed(path: str) -> bool:
    """Process wide convenience wrapper around :meth:`ConfigStore.reload_if_changed`."""
    key = os.path.abspath(path)
    store = _STORES.get(key)
    if store is None:
        store = _STORES[key] = ConfigStore(path)
    return store.reload_if_changed()

"""Rate limit algorithms plus the append only usage ledger and audit trail.

Every algorithm is a pure function of the injected ``now_ms``: no wall clock,
no sleeping and no randomness, so behaviour is fully reproducible in tests.
"""

from __future__ import annotations

import json
import math
import os
from collections import deque
from typing import Any, Deque, Dict, Iterable, List, Optional

from .config import GatewayError, QuotaPolicy


def _append_jsonl(path: str, entry: Dict[str, Any]) -> None:
    """Append one JSON line in a single write, so a crash cannot split a record."""
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    line = json.dumps(entry, sort_keys=True, separators=(",", ":")) + "\n"
    with open(path, "a", encoding="utf-8") as handle:
        handle.write(line)


def _read_jsonl(path: str) -> List[Dict[str, Any]]:
    """Read JSON lines, skipping a torn trailing line left behind by a crash."""
    if not os.path.exists(path):
        return []
    rows: List[Dict[str, Any]] = []
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            try:
                row = json.loads(line)
            except ValueError:
                continue
            if isinstance(row, dict):
                rows.append(row)
    return rows


def _wait_ms(need: float, rate: float) -> int:
    return int(math.ceil(need / rate)) if rate > 0 and need > 0 else 0


class TokenBucket:
    """Capacity ``capacity``, refilling ``rate`` tokens per millisecond.

    ``tokens(n) = min(capacity, tokens(n-1) + (now - last) * rate)``; a request of
    ``cost`` is admitted when ``tokens >= cost`` and then pays ``cost``.
    """

    algorithm = "token-bucket"

    def __init__(self, capacity: int, rate_per_ms: float) -> None:
        self.capacity = float(capacity)
        self.rate = float(rate_per_ms)
        self.tokens = float(capacity)
        self.last_ms: Optional[int] = None

    def allow(self, cost: int = 1, now_ms: int = 0) -> Dict[str, Any]:
        now_ms = int(now_ms)
        if self.last_ms is None:
            self.last_ms = now_ms
        elapsed = max(0, now_ms - self.last_ms)
        self.last_ms = max(self.last_ms, now_ms)
        self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)
        allowed = self.tokens >= cost
        if allowed:
            self.tokens -= cost
        return {"allowed": allowed, "remaining": max(0, int(self.tokens)),
                "reset_at_ms": now_ms + _wait_ms(max(0.0, cost - self.tokens), self.rate),
                "algorithm": self.algorithm, "limit": int(self.capacity)}


class LeakyBucket:
    """Queue free leaky bucket: the level rises by ``cost`` and leaks at ``rate``.

    A request is rejected as soon as ``level + cost > capacity``; nothing is
    queued, so the caller sees the rejection immediately.
    """

    algorithm = "leaky-bucket"

    def __init__(self, capacity: int, rate_per_ms: float) -> None:
        self.capacity = float(capacity)
        self.rate = float(rate_per_ms)
        self.level = 0.0
        self.last_ms: Optional[int] = None

    def allow(self, cost: int = 1, now_ms: int = 0) -> Dict[str, Any]:
        now_ms = int(now_ms)
        if self.last_ms is None:
            self.last_ms = now_ms
        elapsed = max(0, now_ms - self.last_ms)
        self.last_ms = max(self.last_ms, now_ms)
        self.level = max(0.0, self.level - elapsed * self.rate)
        allowed = self.level + cost <= self.capacity
        if allowed:
            self.level += cost
        need = max(0.0, self.level + cost - self.capacity)
        return {"allowed": allowed, "remaining": max(0, int(self.capacity - self.level)),
                "reset_at_ms": now_ms + _wait_ms(need, self.rate),
                "algorithm": self.algorithm, "limit": int(self.capacity)}


class SlidingWindow:
    """Exact count of admitted timestamps inside the trailing ``window_ms``."""

    algorithm = "sliding-window"

    def __init__(self, limit: int, window_ms: int) -> None:
        self.limit = int(limit)
        self.window_ms = int(window_ms)
        self.stamps: Deque[int] = deque()

    def allow(self, cost: int = 1, now_ms: int = 0) -> Dict[str, Any]:
        now_ms = int(now_ms)
        cutoff = now_ms - self.window_ms
        while self.stamps and self.stamps[0] <= cutoff:
            self.stamps.popleft()
        allowed = len(self.stamps) + cost <= self.limit
        if allowed:
            self.stamps.extend([now_ms] * cost)
        remaining = max(0, self.limit - len(self.stamps))
        if remaining >= cost:
            reset_at_ms = now_ms
        else:  # the (cost - remaining)-th oldest stamp has to expire first
            index = max(0, min(len(self.stamps) - self.limit + cost - 1, len(self.stamps) - 1))
            reset_at_ms = self.stamps[index] + self.window_ms
        return {"allowed": allowed, "remaining": remaining, "reset_at_ms": reset_at_ms,
                "algorithm": self.algorithm, "limit": self.limit}


def make_bucket(policy: QuotaPolicy):
    if policy.algorithm == "token-bucket":
        return TokenBucket(policy.capacity(), policy.rate_per_ms())
    if policy.algorithm == "leaky-bucket":
        return LeakyBucket(policy.capacity(), policy.rate_per_ms())
    return SlidingWindow(policy.limit, policy.window_ms)


class Limiter:
    """Registry of policy id -> bucket; unchanged buckets keep their state."""

    def __init__(self, policies: Optional[Iterable[Any]] = None) -> None:
        self._policies: Dict[str, QuotaPolicy] = {}
        self._buckets: Dict[str, tuple] = {}
        if policies:
            self.sync(policies)

    def sync(self, policies: Iterable[Any]) -> None:
        wanted = {}
        for item in policies:
            policy = item if isinstance(item, QuotaPolicy) else QuotaPolicy.from_dict(item)
            wanted[policy.id] = policy
        self._buckets = {k: v for k, v in self._buckets.items() if k in wanted}
        self._policies = wanted

    def set_policy(self, policy: Any) -> QuotaPolicy:
        parsed = policy if isinstance(policy, QuotaPolicy) else QuotaPolicy.from_dict(policy)
        self._policies[parsed.id] = parsed
        return parsed

    def bucket(self, policy_id: str):
        policy = self._policies.get(policy_id)
        if policy is None:
            raise GatewayError("unknown quota policy: %s" % policy_id, 404)
        current = self._buckets.get(policy_id)
        if current is None or current[0] != policy.signature():
            current = (policy.signature(), make_bucket(policy))
            self._buckets[policy_id] = current
        return current[1]

    def allow(self, policy_id: str, cost: int = 1, now_ms: int = 0) -> Dict[str, Any]:
        result = self.bucket(policy_id).allow(cost, now_ms)
        result["policy_id"] = policy_id
        return result


class QuotaLedger:
    """Append only usage entries persisted as ``<root>/usage.jsonl``."""

    def __init__(self, root: str = "gwd_data") -> None:
        self.root = root
        self.path = os.path.join(root, "usage.jsonl")

    def record(self, tenant: str, policy_id: Optional[str], key_id: Optional[str],
               cost: int, allowed: bool, now_ms: int) -> Dict[str, Any]:
        entry = {"at": int(now_ms), "tenant": tenant, "policy_id": policy_id, "key_id": key_id,
                 "cost": int(cost), "allowed": bool(allowed)}
        _append_jsonl(self.path, entry)
        return entry

    def entries(self, tenant: Optional[str] = None,
                since_ms: Optional[int] = None) -> List[Dict[str, Any]]:
        rows = _read_jsonl(self.path)
        if tenant:
            rows = [r for r in rows if r.get("tenant") == tenant]
        if since_ms is not None:
            rows = [r for r in rows if int(r.get("at", 0)) >= int(since_ms)]
        return rows

    def usage(self, tenant: Optional[str] = None, since_ms: Optional[int] = None) -> Dict[str, Any]:
        rows = self.entries(tenant, since_ms)
        by_policy: Dict[str, Dict[str, int]] = {}
        allowed = rejected = cost = allowed_cost = 0
        for row in rows:
            bucket = by_policy.setdefault(str(row.get("policy_id") or "-"),
                                          {"requests": 0, "allowed": 0, "rejected": 0, "cost": 0})
            ok = bool(row.get("allowed"))
            entry_cost = int(row.get("cost", 0))
            bucket["requests"] += 1
            bucket["cost"] += entry_cost
            bucket["allowed" if ok else "rejected"] += 1
            cost += entry_cost
            allowed += 1 if ok else 0
            allowed_cost += entry_cost if ok else 0
            rejected += 0 if ok else 1
        return {"tenant": tenant, "since_ms": since_ms, "requests": len(rows), "allowed": allowed,
                "rejected": rejected, "cost": cost, "allowed_cost": allowed_cost,
                "by_policy": by_policy}


class AuditLog:
    """Append only request audit trail persisted as ``<root>/audit.jsonl``."""

    def __init__(self, root: str = "gwd_data") -> None:
        self.root = root
        self.path = os.path.join(root, "audit.jsonl")

    def append(self, entry: Dict[str, Any]) -> Dict[str, Any]:
        _append_jsonl(self.path, entry)
        return entry

    def entries(self, tenant: Optional[str] = None,
                limit: Optional[int] = None) -> List[Dict[str, Any]]:
        rows = _read_jsonl(self.path)
        if tenant:
            rows = [r for r in rows if r.get("tenant") == tenant]
        if limit is not None and int(limit) > 0:
            rows = rows[-int(limit):]
        return rows

"""Request pipeline: route -> auth -> quota -> idempotency -> breaker -> audit."""

from __future__ import annotations

import hashlib
import hmac
import json
import secrets
import time
import uuid
from typing import Any, Callable, Dict, List, Optional, Tuple

from .breaker import TRANSPORT_ERROR, BreakerRegistry, RetryPolicy
from .config import (ANY_TENANT, ApiKey, ConfigStore, GatewayError, QuotaPolicy,
                     Route, parse, read_raw, save_config, sha256_hex)
from .limits import AuditLog, Limiter, QuotaLedger
from .upstream import UpstreamError, default_registry

REPLAY_HEADER = "X-Idempotent-Replay"
CREDENTIAL_HEADERS = ("authorization", "x-api-key", "x-api-key-secret")
HOP_HEADERS = ("host", "content-length", "connection", "transfer-encoding")


class Gateway:
    """Owns the config store, limiters, ledger, breakers and the request pipeline."""

    def __init__(self, config_path: Optional[str] = None, data_dir: str = "gwd_data",
                 upstreams: Any = None, retry_policy: Optional[RetryPolicy] = None,
                 breaker_settings: Optional[Dict[str, Any]] = None,
                 idempotency_window_ms: int = 600000,
                 sleep_fn: Optional[Callable[[int], None]] = None) -> None:
        self.store = ConfigStore(config_path)
        self.upstreams = upstreams if upstreams is not None else default_registry()
        self.limiter = Limiter()
        self.ledger = QuotaLedger(data_dir)
        self.audit_log = AuditLog(data_dir)
        self.retry_policy = retry_policy or RetryPolicy()
        self.breakers = BreakerRegistry(**(breaker_settings or {}))
        self.idempotency_window_ms = int(idempotency_window_ms)
        self.sleep_fn = sleep_fn
        self._idempotency: Dict[str, Dict[str, Any]] = {}
        self.sync()

    # ------------------------------------------------------------------ state
    def sync(self) -> None:
        """Push the current policies into the limiter without dropping buckets."""
        self.limiter.sync(self.store.config.policies)

    @property
    def config(self):
        return self.store.config

    def reload_config(self) -> bool:
        changed = self.store.reload_if_changed()
        if changed:
            self.sync()
        return changed

    def health(self) -> Dict[str, Any]:
        return {"ok": bool(self.store.ready), "ready": bool(self.store.ready),
                "revision": self.store.revision, "routes": len(self.config.routes),
                "upstreams": len(self.upstreams.names()),
                "config_error": self.store.last_error}

    def usage(self, tenant: str = "", since_ms: Optional[int] = None) -> Dict[str, Any]:
        return self.ledger.usage(tenant or None, since_ms)

    def audit(self, tenant: str = "", limit: int = 50) -> List[Dict[str, Any]]:
        return self.audit_log.entries(tenant or None, limit)

    def breaker_reset(self, name: Optional[str] = None) -> List[str]:
        return self.breakers.reset(name)

    def sanitized_config(self) -> Dict[str, Any]:
        return self.config.sanitized()

    # -------------------------------------------------------------- mutations
    def _mutate(self, mutate: Callable[[Dict[str, Any]], None]) -> None:
        path = self.store.path
        if not path:
            raise GatewayError("no config path: start the gateway with --config to persist changes")
        raw = read_raw(path)
        mutate(raw)
        parsed = parse(raw)          # validate the whole document before writing
        save_config(path, raw)
        self.store.adopt(parsed)
        self.sync()

    def add_route(self, raw: Any) -> Dict[str, Any]:
        items = raw if isinstance(raw, list) else [raw]
        routes = [Route.from_dict(item, "route") for item in items]
        def mutate(document: Dict[str, Any]) -> None:
            existing = {r.get("id") for r in document["routes"]}
            for route in routes:
                if route.id in existing:
                    raise GatewayError("route already exists: %s" % route.id)
                document["routes"].append(route.to_dict())
        self._mutate(mutate)
        return routes[0].to_dict() if len(routes) == 1 else {"routes": [r.to_dict() for r in routes]}

    def add_key(self, tenant: str, scopes: Optional[List[str]] = None,
                key_id: Optional[str] = None) -> Dict[str, Any]:
        if not tenant:
            raise GatewayError("tenant is required")
        secret = secrets.token_urlsafe(24)
        key = ApiKey(key_id=key_id or ("key-" + secrets.token_hex(6)), tenant=tenant,
                     secret_sha256=sha256_hex(secret), scopes=list(scopes or []))
        def mutate(document: Dict[str, Any]) -> None:
            if any(k.get("key_id") == key.key_id for k in document["keys"]):
                raise GatewayError("api key already exists: %s" % key.key_id)
            document["keys"].append(key.to_dict())
        self._mutate(mutate)
        out = key.to_dict()          # the plaintext secret is returned exactly once
        out["secret"] = secret
        return out

    def add_policy(self, raw: Any) -> Dict[str, Any]:
        items = raw if isinstance(raw, list) else [raw]
        policies = [QuotaPolicy.from_dict(item, "quota policy") for item in items]
        def mutate(document: Dict[str, Any]) -> None:
            existing = {p.get("id") for p in document["quota_policies"]}
            for policy in policies:
                if policy.id in existing:
                    raise GatewayError("quota policy already exists: %s" % policy.id)
                document["quota_policies"].append(policy.to_dict())
        self._mutate(mutate)
        return policies[0].to_dict() if len(policies) == 1 else {"policies": [p.to_dict() for p in policies]}

    # --------------------------------------------------------------- pipeline
    def handle(self, tenant: str, method: str, path: str, headers: Optional[Dict[str, str]] = None,
               body: str = "", now_ms: Optional[int] = None) -> Dict[str, Any]:
        """Run one request through the full pipeline and return a response dict."""
        started_ms = int(now_ms if now_ms is not None else time.time() * 1000)
        now = started_ms
        mono = time.monotonic()
        method = (method or "GET").upper()
        body = body or ""
        hdrs = {str(k).lower(): str(v) for k, v in (headers or {}).items()}
        request_id = hdrs.get("x-request-id") or uuid.uuid4().hex[:16]
        route: Optional[Route] = None
        upstream_name: Optional[str] = None
        key: Optional[ApiKey] = None
        quota: Dict[str, Any] = {"policy_id": None, "allowed": True, "remaining": None}
        attempts = 0

        def finish(status: int, payload: Optional[Dict[str, Any]] = None,
                   body_text: Optional[str] = None, extra_headers: Optional[Dict[str, str]] = None,
                   replay: bool = False) -> Dict[str, Any]:
            text = body_text if body_text is not None else json.dumps(payload or {}, sort_keys=True)
            self.audit_log.append({
                "at": now, "request_id": request_id, "tenant": tenant,
                "key_id": key.key_id if key else None,
                "route_id": route.id if route else None,
                "upstream": upstream_name or (route.upstream if route else None),
                "status": int(status), "attempts": attempts,
                "latency_ms": max(now - started_ms, int((time.monotonic() - mono) * 1000)),
                "quota": dict(quota), "idempotent_replay": bool(replay)})
            out_headers: Dict[str, str] = {"Content-Type": "application/json"}
            if route:
                out_headers.update(route.response_headers)
            out_headers.update(extra_headers or {})
            return {"status": int(status), "headers": out_headers, "body": text,
                    "request_id": request_id, "route_id": route.id if route else None}

        key, auth_error = self._resolve_key(hdrs)
        tenant = tenant or (key.tenant if key else "")
        candidates = self.config.matching_routes(method, path, tenant)
        if not candidates:
            # No route for this tenant: retry without the tenant filter so the
            # request is rejected by authentication (401/403) instead of 404.
            candidates = self.config.matching_routes(method, path, None)
        if not candidates:
            return finish(404, {"error": "no route for %s %s" % (method, path), "request_id": request_id})
        selector = "%s|%s" % (key.key_id if key else "-", request_id)
        route = self._pick_route(candidates, selector)

        # 2. authentication and authorisation
        if route.auth_required:
            if auth_error:
                return finish(401, {"error": auth_error, "request_id": request_id})
            if route.tenant != ANY_TENANT and key.tenant != route.tenant:
                return finish(403, {"error": "api key tenant %r is not allowed on route %s"
                                             % (key.tenant, route.id), "request_id": request_id})
            missing = [scope for scope in route.scopes if not key.allows([scope])]
            if missing:
                return finish(403, {"error": "api key is missing required scope(s): %s"
                                             % ",".join(missing), "request_id": request_id})

        # 3. quota
        if route.quota_policy:
            result = self.limiter.allow(route.quota_policy, 1, now)
            quota = {"policy_id": route.quota_policy, "allowed": result["allowed"],
                     "remaining": result["remaining"]}
            self.ledger.record(tenant, route.quota_policy, key.key_id if key else None, 1,
                               result["allowed"], now)
            if not result["allowed"]:
                retry_after = max(1, int((result["reset_at_ms"] - now + 999) // 1000))
                return finish(429, {"error": "quota exceeded", "request_id": request_id,
                                    "policy_id": route.quota_policy,
                                    "reset_at_ms": result["reset_at_ms"]},
                              extra_headers={"Retry-After": str(retry_after)})

        # 4. idempotency
        body_hash = sha256_hex(body)
        idem_key = None
        idem_header = hdrs.get("x-idempotency-key")
        if idem_header:
            idem_key = "%s|%s" % (tenant, idem_header)
            stored = self._idempotency.get(idem_key)
            if stored is not None:
                if stored["expires_ms"] <= now:
                    self._idempotency.pop(idem_key, None)
                elif stored["body_sha256"] != body_hash:
                    return finish(409, {"error": "idempotency key reused with a different request body",
                                        "request_id": request_id})
                else:
                    replay = dict(stored["response"])
                    replay_headers = dict(replay.get("headers") or {})
                    replay_headers[REPLAY_HEADER] = "true"
                    return finish(replay["status"], body_text=replay["body"],
                                  extra_headers=replay_headers, replay=True)

        # 5. circuit breaker and upstream call with retries
        upstream_name = route.upstream
        breaker = self.breakers.get(upstream_name)
        if not breaker.allow(now):
            return finish(503, {"error": "upstream unavailable", "state": breaker.state,
                                "request_id": request_id})
        request = {"method": method, "path": path, "body": body, "tenant": tenant,
                   "request_id": request_id, "headers": self._upstream_headers(hdrs, route)}
        response = None
        status = TRANSPORT_ERROR
        while attempts < self.retry_policy.max_attempts:
            attempts += 1
            try:
                response = self.upstreams.call(upstream_name, request, route.timeout_ms)
                status = int(response["status"])
            except UpstreamError:
                response = None
                status = TRANSPORT_ERROR
            if not self.retry_policy.should_retry(attempts, status):
                break
            if self.sleep_fn is not None:
                self.sleep_fn(self.retry_policy.delay_ms(attempts))
        breaker.record(status != TRANSPORT_ERROR and status < 500, now)

        if status == TRANSPORT_ERROR:
            return finish(502, {"error": "upstream error", "request_id": request_id,
                                "upstream": upstream_name})
        text = response["body"] if response else ""
        if idem_key and status < 500:
            self._remember(idem_key, body_hash, now, status, text)
        return finish(status, body_text=text, extra_headers=response.get("headers") if response else None)

    # ---------------------------------------------------------------- helpers
    def _remember(self, idem_key: str, body_hash: str, now: int, status: int, text: str) -> None:
        if len(self._idempotency) > 1024:
            self._idempotency = {k: v for k, v in self._idempotency.items() if v["expires_ms"] > now}
        self._idempotency[idem_key] = {
            "body_sha256": body_hash, "expires_ms": now + self.idempotency_window_ms,
            "response": {"status": int(status), "body": text, "headers": {}}}

    def _resolve_key(self, hdrs: Dict[str, str]) -> Tuple[Optional[ApiKey], Optional[str]]:
        """Resolve the API key from the presented secret; the sha256 is compared."""
        secret = hdrs.get("x-api-key-secret") or ""
        authorization = hdrs.get("authorization") or ""
        if authorization.lower().startswith("bearer "):
            secret = authorization[7:].strip()
        if not secret:
            return None, "missing api key"
        digest = sha256_hex(secret)
        match = None
        for candidate in self.config.keys:
            if hmac.compare_digest(candidate.secret_sha256, digest):
                match = candidate
                break
        if match is None:
            return None, "unknown api key"
        stated = hdrs.get("x-api-key")
        if stated and stated != match.key_id:
            return None, "api key id does not match the presented secret"
        return match, None

    @staticmethod
    def _pick_route(candidates: List[Route], selector: str) -> Route:
        """Longest path prefix wins; ties are resolved by weighted stable hashing.

        ``bucket = int(sha256("<key_id>|<request_id>").hexdigest()[:16], 16) % total_weight``
        then candidates sorted by route id consume the range ``[0, total_weight)``.
        """
        best = max(len(route.path_prefix) for route in candidates)
        pool = sorted((r for r in candidates if len(r.path_prefix) == best), key=lambda r: r.id)
        if len(pool) == 1:
            return pool[0]
        total = sum(route.weight for route in pool)
        bucket = int(hashlib.sha256(selector.encode("utf-8")).hexdigest()[:16], 16) % total
        upto = 0
        for route in pool:
            upto += route.weight
            if bucket < upto:
                return route
        return pool[-1]

    @staticmethod
    def _upstream_headers(hdrs: Dict[str, str], route: Route) -> Dict[str, str]:
        out = {name: value for name, value in hdrs.items()
               if name not in CREDENTIAL_HEADERS and name not in HOP_HEADERS}
        out.update(route.request_headers)
        return out

"""ThreadingHTTPServer front end: admin surface plus the proxy surface."""

from __future__ import annotations

import json
import sys
import time
import urllib.parse
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Dict, Optional, Tuple

from .config import GatewayError
from .gateway import Gateway

ADMIN_GET = ("/healthz", "/v1/config", "/v1/quota/usage", "/v1/audit")
ADMIN_POST = ("/v1/config/reload", "/v1/keys", "/v1/quota/policies", "/v1/breaker/reset")


class GatewayHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: Tuple[str, int], gateway: Gateway, quiet: bool = False) -> None:
        super().__init__(address, GatewayHandler)
        self.gateway = gateway
        self.quiet = quiet


class GatewayHandler(BaseHTTPRequestHandler):
    server_version = "gwd/0.1"
    protocol_version = "HTTP/1.1"

    def do_GET(self) -> None:
        self._dispatch()

    def do_POST(self) -> None:
        self._dispatch()

    def do_PUT(self) -> None:
        self._dispatch()

    def do_PATCH(self) -> None:
        self._dispatch()

    def do_DELETE(self) -> None:
        self._dispatch()

    def log_message(self, fmt: str, *args: Any) -> None:
        if not getattr(self.server, "quiet", False):
            sys.stderr.write("%s %s\n" % (self.address_string(), fmt % args))

    # ------------------------------------------------------------------ plumbing
    def _dispatch(self) -> None:
        gateway: Gateway = self.server.gateway
        now_ms = int(time.time() * 1000)
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length).decode("utf-8", "replace") if length > 0 else ""
        target, _, query = self.path.partition("?")
        params = urllib.parse.parse_qs(query)
        headers = {k.lower(): v for k, v in self.headers.items()}
        request_id = headers.get("x-request-id") or uuid.uuid4().hex[:16]
        try:
            handled = self._admin(gateway, target, raw, params, request_id)
            if handled:
                return
        except GatewayError as exc:
            self._json(exc.status, {"error": exc.message, "request_id": request_id}, request_id)
            return
        except ValueError as exc:
            self._json(400, {"error": str(exc), "request_id": request_id}, request_id)
            return
        path = target
        if path == "/gw":
            path = "/"
        elif path.startswith("/gw/"):
            path = path[3:]
        tenant = _first(params, "tenant") or headers.get("x-tenant") or ""
        response = gateway.handle(tenant, self.command, path, headers, raw, now_ms)
        self._send(response["status"], response["body"], response["headers"])

    def _admin(self, gateway: Gateway, target: str, raw: str,
               params: Dict[str, Any], request_id: str) -> bool:
        if target in ADMIN_GET and self.command != "GET":
            return False
        if target in ADMIN_POST and self.command != "POST":
            return False
        if target == "/healthz":
            self._json(200, gateway.health(), request_id)
        elif target == "/v1/config":
            self._json(200, gateway.sanitized_config(), request_id)
        elif target == "/v1/config/reload":
            reloaded = gateway.reload_config()
            self._json(200, {"reloaded": reloaded, "revision": gateway.store.revision,
                             "ready": bool(gateway.store.ready),
                             "error": gateway.store.last_error}, request_id)
        elif target == "/v1/keys":
            payload = _json_body(raw)
            out = gateway.add_key(payload.get("tenant") or "", payload.get("scopes"),
                                  payload.get("key_id"))
            self._json(201, out, request_id)
        elif target == "/v1/quota/policies":
            self._json(201, gateway.add_policy(_json_body(raw)), request_id)
        elif target == "/v1/quota/usage":
            self._json(200, gateway.usage(_first(params, "tenant") or "",
                                          _int_or_none(_first(params, "since"))), request_id)
        elif target == "/v1/audit":
            tenant = _first(params, "tenant") or ""
            limit = _int_or_none(_first(params, "limit"))
            entries = gateway.audit(tenant, 50 if limit is None else limit)
            self._json(200, {"tenant": tenant, "count": len(entries), "entries": entries}, request_id)
        elif target == "/v1/breaker/reset":
            payload = _json_body(raw, default={})
            self._json(200, {"reset": gateway.breaker_reset(payload.get("upstream"))}, request_id)
        else:
            return False
        return True

    def _json(self, status: int, payload: Any, request_id: str) -> None:
        self._send(status, json.dumps(payload, sort_keys=True), {"X-Request-Id": request_id})

    def _send(self, status: int, text: str, headers: Optional[Dict[str, str]] = None) -> None:
        headers = headers or {}
        payload = (text or "").encode("utf-8")
        self.send_response(int(status))
        has_type = False
        for name, value in headers.items():
            lowered = str(name).lower()
            if lowered in ("content-length", "transfer-encoding", "connection"):
                continue
            if lowered == "content-type":
                has_type = True
            self.send_header(str(name), str(value))
        if not has_type:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if payload:
            self.wfile.write(payload)


def _json_body(raw: str, default: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    if not raw.strip():
        if default is not None:
            return default
        raise GatewayError("request body must be a JSON object")
    try:
        payload = json.loads(raw)
    except ValueError as exc:
        raise GatewayError("request body is not valid JSON: %s" % exc)
    if not isinstance(payload, dict):
        raise GatewayError("request body must be a JSON object")
    return payload


def _first(params: Dict[str, Any], key: str) -> Optional[str]:
    values = params.get(key)
    return values[0] if values else None


def _int_or_none(value: Optional[str]) -> Optional[int]:
    if value is None or value == "":
        return None
    try:
        return int(value)
    except ValueError:
        raise GatewayError("query parameter must be an integer: %s" % value)


def create_server(gateway: Gateway, host: str = "127.0.0.1", port: int = 8080,
                  quiet: bool = False) -> GatewayHTTPServer:
    """Build (but do not start) the HTTP server bound to ``host:port``."""
    return GatewayHTTPServer((host, int(port)), gateway, quiet=quiet)

"""Command line interface: serve, route-add, key-add, quota-set, call, usage, audit."""

from __future__ import annotations

import argparse
import json
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, List, Optional

from .config import ANY_SCOPE, GatewayError
from .gateway import Gateway
from .http_app import create_server
from .limits import AuditLog, QuotaLedger


def _out(payload: Any) -> None:
    sys.stdout.write(json.dumps(payload, sort_keys=True) + "\n")
    sys.stdout.flush()


def _err(message: str) -> int:
    sys.stderr.write(json.dumps({"error": message}, sort_keys=True) + "\n")
    sys.stderr.flush()
    return 1


def _read_json_arg(value: str) -> Any:
    """Read a JSON document from a path, or from stdin when the value is '-'."""
    if value == "-":
        text = sys.stdin.read()
    else:
        try:
            with open(value, "r", encoding="utf-8") as handle:
                text = handle.read()
        except OSError as exc:
            raise GatewayError("cannot read %s: %s" % (value, exc))
    try:
        return json.loads(text)
    except ValueError as exc:
        raise GatewayError("%s is not valid JSON: %s" % (value, exc))


def cmd_serve(args: argparse.Namespace) -> Dict[str, Any]:
    gateway = Gateway(config_path=args.config, data_dir=args.data_dir)
    server = create_server(gateway, args.host, args.port)
    host, port = server.server_address[0], server.server_address[1]
    _out({"listening": "http://%s:%d" % (host, port), "config": args.config,
          "data_dir": args.data_dir, "routes": len(gateway.config.routes),
          "revision": gateway.store.revision})
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return {"stopped": True}


def cmd_route_add(args: argparse.Namespace) -> Dict[str, Any]:
    gateway = Gateway(config_path=args.config, data_dir=args.data_dir)
    return gateway.add_route(_read_json_arg(args.file))


def cmd_key_add(args: argparse.Namespace) -> Dict[str, Any]:
    gateway = Gateway(config_path=args.config, data_dir=args.data_dir)
    scopes: List[str] = args.scopes or [ANY_SCOPE]
    return gateway.add_key(args.tenant, scopes, args.key_id)


def cmd_quota_set(args: argparse.Namespace) -> Dict[str, Any]:
    gateway = Gateway(config_path=args.config, data_dir=args.data_dir)
    return gateway.add_policy(_read_json_arg(args.file))


def cmd_call(args: argparse.Namespace) -> Dict[str, Any]:
    key_id, secret = args.key_id or "", args.key or ""
    if not key_id and ":" in secret:
        key_id, secret = secret.split(":", 1)
    body = args.body or ""
    request = urllib.request.Request(args.base_url.rstrip("/") + args.path,
                                     data=body.encode("utf-8") if body else None,
                                     method=args.method.upper())
    if secret:
        request.add_header("Authorization", "Bearer " + secret)
    if key_id:
        request.add_header("X-Api-Key", key_id)
    if args.tenant:
        request.add_header("X-Tenant", args.tenant)
    if args.idempotency_key:
        request.add_header("X-Idempotency-Key", args.idempotency_key)
    request.add_header("Content-Type", "application/json")
    timeout = max(0.001, args.timeout_ms / 1000.0)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            status, headers = response.status, dict(response.headers)
            text = response.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as exc:
        status, headers = exc.code, dict(exc.headers or {})
        text = exc.read().decode("utf-8", "replace")
    except (urllib.error.URLError, OSError) as exc:
        raise GatewayError("call failed: %s" % exc)
    return {"status": int(status), "replayed": headers.get("X-Idempotent-Replay") == "true",
            "headers": headers, "body": _maybe_json(text)}


def _maybe_json(text: str) -> Any:
    try:
        return json.loads(text)
    except ValueError:
        return text


def cmd_usage(args: argparse.Namespace) -> Dict[str, Any]:
    return QuotaLedger(args.data_dir).usage(args.tenant or None, args.since)


def cmd_audit(args: argparse.Namespace) -> Dict[str, Any]:
    entries = AuditLog(args.data_dir).entries(args.tenant or None, args.limit)
    return {"tenant": args.tenant, "count": len(entries), "entries": entries}


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="gwd", description="API gateway and quota governance backend")
    parser.add_argument("--data-dir", default="./gwd_data",
                        help="directory for usage.jsonl and audit.jsonl (default ./gwd_data)")
    sub = parser.add_subparsers(dest="command", required=True)

    serve = sub.add_parser("serve", help="run the gateway HTTP server")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8080)
    serve.add_argument("--config", default="./config.json")
    serve.set_defaults(func=cmd_serve)

    route_add = sub.add_parser("route-add", help="append a route from a JSON file")
    route_add.add_argument("--file", required=True, help="JSON file with a route object or array")
    route_add.add_argument("--config", default="./config.json")
    route_add.set_defaults(func=cmd_route_add)

    key_add = sub.add_parser("key-add", help="create an API key; prints the secret once")
    key_add.add_argument("--tenant", required=True)
    key_add.add_argument("--scope", action="append", dest="scopes")
    key_add.add_argument("--key-id")
    key_add.add_argument("--config", default="./config.json")
    key_add.set_defaults(func=cmd_key_add)

